// --- myns.FDb.sched1.UpdateCycles
// Update cycles count from previous clock capture
inline static void myns::sched1_UpdateCycles() {
    u64 cur_cycles                      = algo::get_cycles();
    algo_lib::_db.clock                 = algo::SchedTime(cur_cycles);
}

// --- myns.FDb.sched1.Call
inline static void myns::sched1_Call() {
    if (myns::_db.sched1) { // fstep:myns.FDb.sched1
        if (myns::_db.sched1_next < algo_lib::_db.clock) {
            myns::_db.sched1_next = algo_lib::_db.clock + myns::_db.sched1_delay;
            myns::sched1_Step(); // steptype:InlineRecur: call function every N clock cycles
            sched1_UpdateCycles();
        }
        algo_lib::_db.next_loop.value = u64_Min(myns::_db.sched1_next, algo_lib::_db.next_loop);
    }
}

// --- myns.FDb.sched1.SetDelay
// Set inter-step delay to specified value.
// The difference between new delay and current delay is added to the next scheduled time.
void myns::sched1_SetDelay(algo::SchedTime delay) {
    i64 diff = delay.value - myns::_db.sched1_delay.value;
    myns::_db.sched1_delay = delay;
    if (diff > 0) {
        myns::_db.sched1_next.value += diff;
    } else {
        myns::_db.sched1_next.value = algo::u64_SubClip(myns::_db.sched1_next.value,-diff);
    }
}

// --- myns.FDb.client.Alloc
// Allocate memory for new default row.
// If out of memory, process is killed.
myns::Client& myns::client_Alloc() {
    myns::Client* row = client_AllocMaybe();
    if (UNLIKELY(row == NULL)) {
        FatalErrorExit("myns.out_of_mem  field:myns.FDb.client  comment:'Alloc failed'");
    }
    return *row;
}

// --- myns.FDb.client.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
myns::Client* myns::client_AllocMaybe() {
    myns::Client *row = (myns::Client*)client_AllocMem();
    if (row) {
        new (row) myns::Client; // call constructor
    }
    return row;
}

// --- myns.FDb.client.Delete
// Remove row from all global and cross indices, then deallocate row
void myns::client_Delete(myns::Client &row) {
    row.~Client();
    client_FreeMem(row);
}

// --- myns.FDb.client.AllocMem
// Allocate space for one element
// If no memory available, return NULL.
void* myns::client_AllocMem() {
    myns::Client *row = _db.client_free;
    if (UNLIKELY(!row)) {
        client_Reserve(1);
        row = _db.client_free;
    }
    if (row) {
        _db.client_free = row->client_next;
    }
    return row;
}

// --- myns.FDb.client.FreeMem
// Remove mem from all global and cross indices, then deallocate mem
void myns::client_FreeMem(myns::Client &row) {
    if (UNLIKELY(row.client_next != (myns::Client*)-1)) {
        FatalErrorExit("myns.tpool_double_delete  pool:myns.FDb.client  comment:'double deletion caught'");
    }
    row.client_next = _db.client_free; // insert into free list
    _db.client_free  = &row;
}

// --- myns.FDb.client.Reserve
// Preallocate memory for N more elements
// Return number of elements actually reserved.
u64 myns::client_Reserve(u64 n_elems) {
    u64 ret = 0;
    while (ret < n_elems) {
        u64 size = _db.client_blocksize; // underlying allocator is probably Lpool
        u64 reserved = client_ReserveMem(size);
        ret += reserved;
        if (reserved == 0) {
            break;
        }
    }
    return ret;
}

// --- myns.FDb.client.ReserveMem
// Allocate block of given size, break up into small elements and append to free list.
// Return number of elements reserved.
u64 myns::client_ReserveMem(u64 size) {
    u64 ret = 0;
    if (size >= sizeof(myns::Client)) {
        myns::Client *mem = (myns::Client*)algo_lib::malloc_AllocMem(size);
        ret = mem ? size / sizeof(myns::Client) : 0;
        // add newly allocated elements to the free list;
        for (u64 i=0; i < ret; i++) {
            mem[i].client_next = _db.client_free;
            _db.client_free = mem+i;
        }
    }
    return ret;
}

// --- myns.FDb.client.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool myns::client_XrefMaybe(myns::Client &row) {
    bool retval = true;
    (void)row;
    // insert client into index ind_client
    if (true) { // user-defined insert condition
        bool success = ind_client_InsertMaybe(row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "myns.duplicate_key  xref:myns.FDb.ind_client"; // check for duplicate key
            return false;
        }
    }
    return retval;
}

// --- myns.FDb.ind_client.Find
// Find row by key. Return NULL if not found.
myns::Client* myns::ind_client_Find(const algo::strptr& key) {
    u32 index = algo::Smallstr50_Hash(0, key) & (_db.ind_client_buckets_n - 1);
    myns::Client* *e = &_db.ind_client_buckets_elems[index];
    myns::Client* ret=NULL;
    do {
        ret       = *e;
        bool done = !ret || (*ret).client == key;
        if (done) break;
        e         = &ret->ind_client_next;
    } while (true);
    return ret;
}

// --- myns.FDb.ind_client.FindX
// Look up row by key and return reference. Throw exception if not found
myns::Client& myns::ind_client_FindX(const algo::strptr& key) {
    myns::Client* ret = ind_client_Find(key);
    vrfy(ret, tempstr() << "myns.key_error  table:ind_client  key:'"<<key<<"'  comment:'key not found'");
    return *ret;
}

// --- myns.FDb.ind_client.GetOrCreate
// Find row by key. If not found, create and x-reference a new row with with this key.
myns::Client& myns::ind_client_GetOrCreate(const algo::strptr& key) {
    myns::Client* ret = ind_client_Find(key);
    if (!ret) { //  if memory alloc fails, process dies; if insert fails, function returns NULL.
        ret         = &client_Alloc();
        (*ret).client = key;
        bool good = client_XrefMaybe(*ret);
        if (!good) {
            client_Delete(*ret); // delete offending row, any existin xrefs are cleared
            ret = NULL;
        }
    }
    vrfy(ret, tempstr() << "myns.create_error  table:ind_client  key:'"<<key<<"'  comment:'bad xref'");
    return *ret;
}

// --- myns.FDb.ind_client.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool myns::ind_client_InsertMaybe(myns::Client& row) {
    ind_client_Reserve(1);
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_client_next == (myns::Client*)-1)) {// check if in hash already
        u32 index = algo::Smallstr50_Hash(0, row.client) & (_db.ind_client_buckets_n - 1);
        myns::Client* *prev = &_db.ind_client_buckets_elems[index];
        do {
            myns::Client* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).client == row.client) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_client_next;
        } while (true);
        if (retval) {
            row.ind_client_next = *prev;
            _db.ind_client_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- myns.FDb.ind_client.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void myns::ind_client_Remove(myns::Client& row) {
    if (LIKELY(row.ind_client_next != (myns::Client*)-1)) {// check if in hash already
        u32 index = algo::Smallstr50_Hash(0, row.client) & (_db.ind_client_buckets_n - 1);
        myns::Client* *prev = &_db.ind_client_buckets_elems[index]; // addr of pointer to current element
        while (myns::Client *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_client_next; // unlink (singly linked list)
                _db.ind_client_n--;
                row.ind_client_next = (myns::Client*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_client_next;
        }
    }
}

// --- myns.FDb.ind_client.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void myns::ind_client_Reserve(int n) {
    u32 old_nbuckets = _db.ind_client_buckets_n;
    u32 new_nelems   = _db.ind_client_n + n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(myns::Client*);
        u32 new_size = new_nbuckets * sizeof(myns::Client*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        myns::Client* *new_buckets = (myns::Client**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("myns.out_of_memory  field:myns.FDb.ind_client");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_client_buckets_n; i++) {
            myns::Client* elem = _db.ind_client_buckets_elems[i];
            while (elem) {
                myns::Client &row        = *elem;
                myns::Client* next       = row.ind_client_next;
                u32 index          = algo::Smallstr50_Hash(0, row.client) & (new_nbuckets-1);
                row.ind_client_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_client_buckets_elems, old_size);
        _db.ind_client_buckets_elems = new_buckets;
        _db.ind_client_buckets_n = new_nbuckets;
    }
}

// --- myns.FDb.part.Alloc
// Allocate memory for new default row.
// If out of memory, process is killed.
myns::FPart& myns::part_Alloc() {
    myns::FPart* row = part_AllocMaybe();
    if (UNLIKELY(row == NULL)) {
        FatalErrorExit("myns.out_of_mem  field:myns.FDb.part  comment:'Alloc failed'");
    }
    return *row;
}

// --- myns.FDb.part.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
myns::FPart* myns::part_AllocMaybe() {
    myns::FPart *row = (myns::FPart*)part_AllocMem();
    if (row) {
        new (row) myns::FPart; // call constructor
    }
    return row;
}

// --- myns.FDb.part.InsertMaybe
// Create new row from struct.
// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
myns::FPart* myns::part_InsertMaybe(const mynsdb::Part &value) {
    myns::FPart *row = &part_Alloc(); // if out of memory, process dies. if input error, return NULL.
    part_CopyIn(*row,const_cast<mynsdb::Part&>(value));
    bool ok = part_XrefMaybe(*row); // this may return false
    if (!ok) {
        part_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- myns.FDb.part.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* myns::part_AllocMem() {
    u64 new_nelems     = _db.part_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    myns::FPart*  lev   = NULL;
    if (bsr < 32) {
        lev = _db.part_lary[bsr];
        if (!lev) {
            lev=(myns::FPart*)algo_lib::malloc_AllocMem(sizeof(myns::FPart) * (u64(1)<<bsr));
            _db.part_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.part_n = i32(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- myns.FDb.part.RemoveAll
// Remove all elements from Lary
void myns::part_RemoveAll() {
    for (u64 n = _db.part_n; n>0; ) {
        n--;
        part_qFind(u64(n)).~FPart(); // destroy last element
        _db.part_n = i32(n);
    }
}

// --- myns.FDb.part.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void myns::part_RemoveLast() {
    u64 n = _db.part_n;
    if (n > 0) {
        n -= 1;
        part_qFind(u64(n)).~FPart();
        _db.part_n = i32(n);
    }
}

// --- myns.FDb.part.InputMaybe
static bool myns::part_InputMaybe(mynsdb::Part &elem) {
    bool retval = true;
    retval = part_InsertMaybe(elem) != nullptr;
    return retval;
}

// --- myns.FDb.part.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool myns::part_XrefMaybe(myns::FPart &row) {
    bool retval = true;
    (void)row;
    // insert part into index zd_part
    if (true) { // user-defined insert condition
        zd_part_Insert(row);
    }
    // insert part into index ind_part
    if (true) { // user-defined insert condition
        bool success = ind_part_InsertMaybe(row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "myns.duplicate_key  xref:myns.FDb.ind_part"; // check for duplicate key
            return false;
        }
    }
    return retval;
}

// --- myns.FDb.zd_part.Insert
// Insert row into linked list. If row is already in linked list, do nothing.
void myns::zd_part_Insert(myns::FPart& row) {
    if (!zd_part_InLlistQ(row)) {
        myns::FPart* old_tail = _db.zd_part_tail;
        row.zd_part_next = NULL;
        row.zd_part_prev = old_tail;
        _db.zd_part_tail = &row;
        myns::FPart **new_row_a = &old_tail->zd_part_next;
        myns::FPart **new_row_b = &_db.zd_part_head;
        myns::FPart **new_row = old_tail ? new_row_a : new_row_b;
        *new_row = &row;
        _db.zd_part_n++;
    }
}

// --- myns.FDb.zd_part.Remove
// Remove element from index. If element is not in index, do nothing.
void myns::zd_part_Remove(myns::FPart& row) {
    if (zd_part_InLlistQ(row)) {
        myns::FPart* old_head       = _db.zd_part_head;
        (void)old_head; // in case it's not used
        myns::FPart* prev = row.zd_part_prev;
        myns::FPart* next = row.zd_part_next;
        // if element is first, adjust list head; otherwise, adjust previous element's next
        myns::FPart **new_next_a = &prev->zd_part_next;
        myns::FPart **new_next_b = &_db.zd_part_head;
        myns::FPart **new_next = prev ? new_next_a : new_next_b;
        *new_next = next;
        // if element is last, adjust list tail; otherwise, adjust next element's prev
        myns::FPart **new_prev_a = &next->zd_part_prev;
        myns::FPart **new_prev_b = &_db.zd_part_tail;
        myns::FPart **new_prev = next ? new_prev_a : new_prev_b;
        *new_prev = prev;
        _db.zd_part_n--;
        row.zd_part_next=(myns::FPart*)-1; // not-in-list
    }
}

// --- myns.FDb.zd_part.RemoveAll
// Empty the index. (The rows are not deleted)
void myns::zd_part_RemoveAll() {
    myns::FPart* row = _db.zd_part_head;
    _db.zd_part_head = NULL;
    _db.zd_part_tail = NULL;
    _db.zd_part_n = 0;
    while (row) {
        myns::FPart* row_next = row->zd_part_next;
        row->zd_part_next  = (myns::FPart*)-1;
        row->zd_part_prev  = NULL;
        row = row_next;
    }
}

// --- myns.FDb.zd_part.RemoveFirst
// If linked list is empty, return NULL. Otherwise unlink and return pointer to first element.
myns::FPart* myns::zd_part_RemoveFirst() {
    myns::FPart *row = NULL;
    row = _db.zd_part_head;
    if (row) {
        myns::FPart *next = row->zd_part_next;
        _db.zd_part_head = next;
        myns::FPart **new_end_a = &next->zd_part_prev;
        myns::FPart **new_end_b = &_db.zd_part_tail;
        myns::FPart **new_end = next ? new_end_a : new_end_b;
        *new_end = NULL;
        _db.zd_part_n--;
        row->zd_part_next = (myns::FPart*)-1; // mark as not-in-list
    }
    return row;
}

// --- myns.FDb.ind_part.Find
// Find row by key. Return NULL if not found.
myns::FPart* myns::ind_part_Find(const algo::strptr& key) {
    u32 index = algo::Smallstr50_Hash(0, key) & (_db.ind_part_buckets_n - 1);
    myns::FPart* *e = &_db.ind_part_buckets_elems[index];
    myns::FPart* ret=NULL;
    do {
        ret       = *e;
        bool done = !ret || (*ret).part == key;
        if (done) break;
        e         = &ret->ind_part_next;
    } while (true);
    return ret;
}

// --- myns.FDb.ind_part.FindX
// Look up row by key and return reference. Throw exception if not found
myns::FPart& myns::ind_part_FindX(const algo::strptr& key) {
    myns::FPart* ret = ind_part_Find(key);
    vrfy(ret, tempstr() << "myns.key_error  table:ind_part  key:'"<<key<<"'  comment:'key not found'");
    return *ret;
}

// --- myns.FDb.ind_part.GetOrCreate
// Find row by key. If not found, create and x-reference a new row with with this key.
myns::FPart& myns::ind_part_GetOrCreate(const algo::strptr& key) {
    myns::FPart* ret = ind_part_Find(key);
    if (!ret) { //  if memory alloc fails, process dies; if insert fails, function returns NULL.
        ret         = &part_Alloc();
        (*ret).part = key;
        bool good = part_XrefMaybe(*ret);
        if (!good) {
            part_RemoveLast(); // delete offending row, any existing xrefs are cleared
            ret = NULL;
        }
    }
    vrfy(ret, tempstr() << "myns.create_error  table:ind_part  key:'"<<key<<"'  comment:'bad xref'");
    return *ret;
}

// --- myns.FDb.ind_part.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool myns::ind_part_InsertMaybe(myns::FPart& row) {
    ind_part_Reserve(1);
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_part_next == (myns::FPart*)-1)) {// check if in hash already
        u32 index = algo::Smallstr50_Hash(0, row.part) & (_db.ind_part_buckets_n - 1);
        myns::FPart* *prev = &_db.ind_part_buckets_elems[index];
        do {
            myns::FPart* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).part == row.part) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_part_next;
        } while (true);
        if (retval) {
            row.ind_part_next = *prev;
            _db.ind_part_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- myns.FDb.ind_part.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void myns::ind_part_Remove(myns::FPart& row) {
    if (LIKELY(row.ind_part_next != (myns::FPart*)-1)) {// check if in hash already
        u32 index = algo::Smallstr50_Hash(0, row.part) & (_db.ind_part_buckets_n - 1);
        myns::FPart* *prev = &_db.ind_part_buckets_elems[index]; // addr of pointer to current element
        while (myns::FPart *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_part_next; // unlink (singly linked list)
                _db.ind_part_n--;
                row.ind_part_next = (myns::FPart*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_part_next;
        }
    }
}

// --- myns.FDb.ind_part.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void myns::ind_part_Reserve(int n) {
    u32 old_nbuckets = _db.ind_part_buckets_n;
    u32 new_nelems   = _db.ind_part_n + n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(myns::FPart*);
        u32 new_size = new_nbuckets * sizeof(myns::FPart*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        myns::FPart* *new_buckets = (myns::FPart**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("myns.out_of_memory  field:myns.FDb.ind_part");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_part_buckets_n; i++) {
            myns::FPart* elem = _db.ind_part_buckets_elems[i];
            while (elem) {
                myns::FPart &row        = *elem;
                myns::FPart* next       = row.ind_part_next;
                u32 index          = algo::Smallstr50_Hash(0, row.part) & (new_nbuckets-1);
                row.ind_part_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_part_buckets_elems, old_size);
        _db.ind_part_buckets_elems = new_buckets;
        _db.ind_part_buckets_n = new_nbuckets;
    }
}

// --- myns.FDb.order.Alloc
// Allocate memory for new default row.
// If out of memory, process is killed.
myns::Order& myns::order_Alloc() {
    myns::Order* row = order_AllocMaybe();
    if (UNLIKELY(row == NULL)) {
        FatalErrorExit("myns.out_of_mem  field:myns.FDb.order  comment:'Alloc failed'");
    }
    return *row;
}

// --- myns.FDb.order.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
myns::Order* myns::order_AllocMaybe() {
    myns::Order *row = (myns::Order*)order_AllocMem();
    if (row) {
        new (row) myns::Order; // call constructor
    }
    return row;
}

// --- myns.FDb.order.Delete
// Remove row from all global and cross indices, then deallocate row
void myns::order_Delete(myns::Order &row) {
    row.~Order();
    order_FreeMem(row);
}

// --- myns.FDb.order.AllocMem
// Allocate space for one element
// If no memory available, return NULL.
void* myns::order_AllocMem() {
    myns::Order *row = _db.order_free;
    if (UNLIKELY(!row)) {
        order_Reserve(1);
        row = _db.order_free;
    }
    if (row) {
        _db.order_free = row->order_next;
    }
    return row;
}

// --- myns.FDb.order.FreeMem
// Remove mem from all global and cross indices, then deallocate mem
void myns::order_FreeMem(myns::Order &row) {
    if (UNLIKELY(row.order_next != (myns::Order*)-1)) {
        FatalErrorExit("myns.tpool_double_delete  pool:myns.FDb.order  comment:'double deletion caught'");
    }
    row.order_next = _db.order_free; // insert into free list
    _db.order_free  = &row;
}

// --- myns.FDb.order.Reserve
// Preallocate memory for N more elements
// Return number of elements actually reserved.
u64 myns::order_Reserve(u64 n_elems) {
    u64 ret = 0;
    while (ret < n_elems) {
        u64 size = _db.order_blocksize; // underlying allocator is probably Lpool
        u64 reserved = order_ReserveMem(size);
        ret += reserved;
        if (reserved == 0) {
            break;
        }
    }
    return ret;
}

// --- myns.FDb.order.ReserveMem
// Allocate block of given size, break up into small elements and append to free list.
// Return number of elements reserved.
u64 myns::order_ReserveMem(u64 size) {
    u64 ret = 0;
    if (size >= sizeof(myns::Order)) {
        myns::Order *mem = (myns::Order*)algo_lib::malloc_AllocMem(size);
        ret = mem ? size / sizeof(myns::Order) : 0;
        // add newly allocated elements to the free list;
        for (u64 i=0; i < ret; i++) {
            mem[i].order_next = _db.order_free;
            _db.order_free = mem+i;
        }
    }
    return ret;
}

// --- myns.FDb.order.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool myns::order_XrefMaybe(myns::Order &row) {
    bool retval = true;
    (void)row;
    // insert order into index ind_order
    if (true) { // user-defined insert condition
        bool success = ind_order_InsertMaybe(row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "myns.duplicate_key  xref:myns.FDb.ind_order"; // check for duplicate key
            return false;
        }
    }
    // insert order into index zd_order
    if (true) { // user-defined insert condition
        zd_order_Insert(row);
    }
    myns::FPart* p_p_part = row.p_part;
    if (UNLIKELY(!p_p_part)) {
        algo_lib::ResetErrtext() << "myns.null_ref  xref:myns.FPart.zd_partorder";
        return false;
    }
    // insert order into index zd_partorder
    if (true) { // user-defined insert condition
        zd_partorder_Insert(*p_p_part, row);
    }
    return retval;
}

