// --- myns.FDb..Init
// Set all fields to initial values.
void myns::FDb_Init() {
    _db.cd_client_eof_head = NULL; // (myns.FDb.cd_client_eof)
    _db.cd_client_eof_n = 0; // (myns.FDb.cd_client_eof)
    _db.cd_client_read_head = NULL; // (myns.FDb.cd_client_read)
    _db.cd_client_read_n = 0; // (myns.FDb.cd_client_read)
    _db.sched1 = bool(true);
    myns::_db.sched1_delay = algo::ToSchedTime(5); // initialize fstep delay (myns.FDb.sched1)
    // client: initialize Tpool
    _db.client_free      = NULL;
    _db.client_blocksize = algo::BumpToPow2(64 * sizeof(myns::Client)); // allocate 64-127 elements at a time
    // initialize hash table for myns::Client;
    _db.ind_client_n             	= 0; // (myns.FDb.ind_client)
    _db.ind_client_buckets_n     	= 4; // (myns.FDb.ind_client)
    _db.ind_client_buckets_elems 	= (myns::Client**)algo_lib::malloc_AllocMem(sizeof(myns::Client*)*_db.ind_client_buckets_n); // initial buckets (myns.FDb.ind_client)
    if (!_db.ind_client_buckets_elems) {
        FatalErrorExit("out of memory"); // (myns.FDb.ind_client)
    }
    memset(_db.ind_client_buckets_elems, 0, sizeof(myns::Client*)*_db.ind_client_buckets_n); // (myns.FDb.ind_client)
    // initialize LAry part (myns.FDb.part)
    _db.part_n = 0;
    memset(_db.part_lary, 0, sizeof(_db.part_lary)); // zero out all level pointers
    myns::FPart* part_first = (myns::FPart*)algo_lib::malloc_AllocMem(sizeof(myns::FPart) * (u64(1)<<4));
    if (!part_first) {
        FatalErrorExit("out of memory");
    }
    for (int i = 0; i < 4; i++) {
        _db.part_lary[i]  = part_first;
        part_first    += 1ULL<<i;
    }
    _db.zd_part_head = NULL; // (myns.FDb.zd_part)
    _db.zd_part_n = 0; // (myns.FDb.zd_part)
    _db.zd_part_tail = NULL; // (myns.FDb.zd_part)
    // initialize hash table for myns::FPart;
    _db.ind_part_n             	= 0; // (myns.FDb.ind_part)
    _db.ind_part_buckets_n     	= 4; // (myns.FDb.ind_part)
    _db.ind_part_buckets_elems 	= (myns::FPart**)algo_lib::malloc_AllocMem(sizeof(myns::FPart*)*_db.ind_part_buckets_n); // initial buckets (myns.FDb.ind_part)
    if (!_db.ind_part_buckets_elems) {
        FatalErrorExit("out of memory"); // (myns.FDb.ind_part)
    }
    memset(_db.ind_part_buckets_elems, 0, sizeof(myns::FPart*)*_db.ind_part_buckets_n); // (myns.FDb.ind_part)
    // order: initialize Tpool
    _db.order_free      = NULL;
    _db.order_blocksize = algo::BumpToPow2(64 * sizeof(myns::Order)); // allocate 64-127 elements at a time
    // initialize hash table for myns::Order;
    _db.ind_order_n             	= 0; // (myns.FDb.ind_order)
    _db.ind_order_buckets_n     	= 4; // (myns.FDb.ind_order)
    _db.ind_order_buckets_elems 	= (myns::Order**)algo_lib::malloc_AllocMem(sizeof(myns::Order*)*_db.ind_order_buckets_n); // initial buckets (myns.FDb.ind_order)
    if (!_db.ind_order_buckets_elems) {
        FatalErrorExit("out of memory"); // (myns.FDb.ind_order)
    }
    memset(_db.ind_order_buckets_elems, 0, sizeof(myns::Order*)*_db.ind_order_buckets_n); // (myns.FDb.ind_order)
    _db.zd_order_head = NULL; // (myns.FDb.zd_order)
    _db.zd_order_n = 0; // (myns.FDb.zd_order)
    _db.zd_order_tail = NULL; // (myns.FDb.zd_order)
    myns::_db.zd_order_delay = algo::ToSchedTime(5); // initialize fstep delay (myns.FDb.zd_order)

    myns::InitReflection();
}

