// --- myns.FPart.zd_partorder.Cascdel
// Delete all elements in the linked list.
void myns::zd_partorder_Cascdel(myns::FPart& part) {
    while (myns::Order *zd_partorder_first = zd_partorder_First(part)) {
        order_Delete(*zd_partorder_first);
    }
}

// --- myns.FPart.zd_partorder.Insert
// Insert row into linked list. If row is already in linked list, do nothing.
void myns::zd_partorder_Insert(myns::FPart& part, myns::Order& row) {
    if (!zd_partorder_InLlistQ(row)) {
        myns::Order* old_tail = part.zd_partorder_tail;
        row.zd_partorder_next = NULL;
        row.zd_partorder_prev = old_tail;
        part.zd_partorder_tail = &row;
        myns::Order **new_row_a = &old_tail->zd_partorder_next;
        myns::Order **new_row_b = &part.zd_partorder_head;
        myns::Order **new_row = old_tail ? new_row_a : new_row_b;
        *new_row = &row;
        part.zd_partorder_n++;
    }
}

// --- myns.FPart.zd_partorder.Remove
// Remove element from index. If element is not in index, do nothing.
void myns::zd_partorder_Remove(myns::FPart& part, myns::Order& row) {
    if (zd_partorder_InLlistQ(row)) {
        myns::Order* old_head       = part.zd_partorder_head;
        (void)old_head; // in case it's not used
        myns::Order* prev = row.zd_partorder_prev;
        myns::Order* next = row.zd_partorder_next;
        // if element is first, adjust list head; otherwise, adjust previous element's next
        myns::Order **new_next_a = &prev->zd_partorder_next;
        myns::Order **new_next_b = &part.zd_partorder_head;
        myns::Order **new_next = prev ? new_next_a : new_next_b;
        *new_next = next;
        // if element is last, adjust list tail; otherwise, adjust next element's prev
        myns::Order **new_prev_a = &next->zd_partorder_prev;
        myns::Order **new_prev_b = &part.zd_partorder_tail;
        myns::Order **new_prev = next ? new_prev_a : new_prev_b;
        *new_prev = prev;
        part.zd_partorder_n--;
        row.zd_partorder_next=(myns::Order*)-1; // not-in-list
    }
}

// --- myns.FPart.zd_partorder.RemoveAll
// Empty the index. (The rows are not deleted)
void myns::zd_partorder_RemoveAll(myns::FPart& part) {
    myns::Order* row = part.zd_partorder_head;
    part.zd_partorder_head = NULL;
    part.zd_partorder_tail = NULL;
    part.zd_partorder_n = 0;
    while (row) {
        myns::Order* row_next = row->zd_partorder_next;
        row->zd_partorder_next  = (myns::Order*)-1;
        row->zd_partorder_prev  = NULL;
        row = row_next;
    }
}

// --- myns.FPart.zd_partorder.RemoveFirst
// If linked list is empty, return NULL. Otherwise unlink and return pointer to first element.
myns::Order* myns::zd_partorder_RemoveFirst(myns::FPart& part) {
    myns::Order *row = NULL;
    row = part.zd_partorder_head;
    if (row) {
        myns::Order *next = row->zd_partorder_next;
        part.zd_partorder_head = next;
        myns::Order **new_end_a = &next->zd_partorder_prev;
        myns::Order **new_end_b = &part.zd_partorder_tail;
        myns::Order **new_end = next ? new_end_a : new_end_b;
        *new_end = NULL;
        part.zd_partorder_n--;
        row->zd_partorder_next = (myns::Order*)-1; // mark as not-in-list
    }
    return row;
}

// --- myns.FPart..Uninit
void myns::FPart_Uninit(myns::FPart& part) {
    myns::FPart &row = part; (void)row;
    zd_partorder_Cascdel(part); // dmmeta.cascdel:myns.FPart.zd_partorder
    zd_part_Remove(row); // remove part from index zd_part
    ind_part_Remove(row); // remove part from index ind_part
}

// --- myns.FieldId.value.ToCstr
// Convert numeric value of field to one of predefined string constants.
// If string is found, return a static C string. Otherwise, return NULL.
const char* myns::value_ToCstr(const myns::FieldId& parent) {
    const char *ret = NULL;
    switch(value_GetEnum(parent)) {
        case myns_FieldId_type             : ret = "type";  break;
        case myns_FieldId_length           : ret = "length";  break;
        case myns_FieldId_base             : ret = "base";  break;
        case myns_FieldId_part_key         : ret = "part_key";  break;
        case myns_FieldId_amt              : ret = "amt";  break;
        case myns_FieldId_value            : ret = "value";  break;
    }
    return ret;
}

// --- myns.FieldId.value.Print
// Convert value to a string. First, attempt conversion to a known string.
// If no string matches, print value as a numeric value.
void myns::value_Print(const myns::FieldId& parent, algo::cstring &lhs) {
    const char *strval = value_ToCstr(parent);
    if (strval) {
        lhs << strval;
    } else {
        lhs << parent.value;
    }
}

// --- myns.FieldId.value.SetStrptrMaybe
// Convert string to field.
// If the string is invalid, do not modify field and return false.
// In case of success, return true
bool myns::value_SetStrptrMaybe(myns::FieldId& parent, algo::strptr rhs) {
    bool ret = false;
    switch (elems_N(rhs)) {
        case 3: {
            switch (u64(algo::ReadLE16(rhs.elems))|(u64(rhs[2])<<16)) {
                case LE_STR3('a','m','t'): {
                    value_SetEnum(parent,myns_FieldId_amt); ret = true; break;
                }
            }
            break;
        }
        case 4: {
            switch (u64(algo::ReadLE32(rhs.elems))) {
                case LE_STR4('b','a','s','e'): {
                    value_SetEnum(parent,myns_FieldId_base); ret = true; break;
                }
                case LE_STR4('t','y','p','e'): {
                    value_SetEnum(parent,myns_FieldId_type); ret = true; break;
                }
            }
            break;
        }
        case 5: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(rhs[4])<<32)) {
                case LE_STR5('v','a','l','u','e'): {
                    value_SetEnum(parent,myns_FieldId_value); ret = true; break;
                }
            }
            break;
        }
        case 6: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(algo::ReadLE16(rhs.elems+4))<<32)) {
                case LE_STR6('l','e','n','g','t','h'): {
                    value_SetEnum(parent,myns_FieldId_length); ret = true; break;
                }
            }
            break;
        }
        case 8: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('p','a','r','t','_','k','e','y'): {
                    value_SetEnum(parent,myns_FieldId_part_key); ret = true; break;
                }
            }
            break;
        }
    }
    return ret;
}

// --- myns.FieldId.value.SetStrptr
