// --- myns.TableId.value.ToCstr
// Convert numeric value of field to one of predefined string constants.
// If string is found, return a static C string. Otherwise, return NULL.
const char* myns::value_ToCstr(const myns::TableId& parent) {
    const char *ret = NULL;
    switch(value_GetEnum(parent)) {
        case myns_TableId_mynsdb_Part      : ret = "mynsdb.Part";  break;
    }
    return ret;
}

// --- myns.TableId.value.Print
// Convert value to a string. First, attempt conversion to a known string.
// If no string matches, print value as a numeric value.
void myns::value_Print(const myns::TableId& parent, algo::cstring &lhs) {
    const char *strval = value_ToCstr(parent);
    if (strval) {
        lhs << strval;
    } else {
        lhs << parent.value;
    }
}

// --- myns.TableId.value.SetStrptrMaybe
// Convert string to field.
// If the string is invalid, do not modify field and return false.
// In case of success, return true
bool myns::value_SetStrptrMaybe(myns::TableId& parent, algo::strptr rhs) {
    bool ret = false;
    switch (elems_N(rhs)) {
        case 11: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('m','y','n','s','d','b','.','P'): {
                    if (memcmp(rhs.elems+8,"art",3)==0) { value_SetEnum(parent,myns_TableId_mynsdb_Part); ret = true; break; }
                    break;
                }
                case LE_STR8('m','y','n','s','d','b','.','p'): {
                    if (memcmp(rhs.elems+8,"art",3)==0) { value_SetEnum(parent,myns_TableId_mynsdb_part); ret = true; break; }
                    break;
                }
            }
            break;
        }
    }
    return ret;
}

// --- myns.TableId.value.SetStrptr
// Convert string to field.
// If the string is invalid, set numeric value to DFLT
void myns::value_SetStrptr(myns::TableId& parent, algo::strptr rhs, myns_TableIdEnum dflt) {
    if (!value_SetStrptrMaybe(parent,rhs)) value_SetEnum(parent,dflt);
}

// --- myns.TableId.value.ReadStrptrMaybe
// Convert string to field. Return success value
bool myns::value_ReadStrptrMaybe(myns::TableId& parent, algo::strptr rhs) {
    bool retval = false;
    retval = value_SetStrptrMaybe(parent,rhs); // try symbol conversion
    if (!retval) { // didn't work? try reading as underlying type
        retval = i32_ReadStrptrMaybe(parent.value,rhs);
    }
    return retval;
}

// --- myns.TableId..ReadStrptrMaybe
// Read fields of myns::TableId from an ascii string.
// The format of the string is the format of the myns::TableId's only field
bool myns::TableId_ReadStrptrMaybe(myns::TableId &parent, algo::strptr in_str) {
    bool retval = true;
    retval = retval && value_ReadStrptrMaybe(parent, in_str);
    return retval;
}

